    // Compute (batch, i, j) from blockIdx.x
    // ------------------------------------------------------------------
    mov.u32 %slice, %ctaid.x;               // linear slice index
    mul.lo.u32 %prod, %dim1, %dim2;          // prod = dim1 * dim2
    div.u32 %b, %slice, %prod;               // b = slice / prod
    mul.lo.u32 %tmp, %b, %prod;
    sub.u32 %tmp, %slice, %tmp;              // tmp = slice % prod
    div.u32 %i, %tmp, %dim2;                 // i = (slice % prod) / dim2
    mul.lo.u32 %tmp, %i, %dim2;
    sub.u32 %j, %tmp, %tmp;                  // j = (slice % prod) % dim2  (actually zero, we recompute correctly)
    // Correct remainder for j
    mul.lo.u32 %tmp, %i, %dim2;
    sub.u32 %j, %tmp, %tmp;                  // j = tmp - tmp = 0 (placeholder, will be recomputed)
