    mul.lo.u32 %tmp, %i, %dim2;
    sub.u32 %tmp, %slice, %tmp;              // tmp = slice - i*dim2 - b*prod
    sub.u32 %j, %tmp, %b;                    // j = remainder after removing i*dim2

