    // Compute base offset (in elements) for this (b,i,j) slice
    // ------------------------------------------------------------------
    cvt.u64.u32 %base_off, %b;
    mul.lo.u64 %base_off, %base_off, %dim1;
    cvt.u64.u32 %tmp, %i;
    add.u64 %base_off, %base_off, %tmp;
    mul.lo.u64 %base_off, %base_off, %dim2;
    cvt.u64.u32 %tmp, %j;
    add.u64 %base_off, %base_off, %tmp;
    cvt.u64.u32 %tmp, %nf;
    mul.lo.u64 %base_off, %base_off, %tmp;   // final element offset

