    cvt.u64.u32 %elem_off, %tid;
    add.u64 %elem_off, %base_off, %elem_off;
    mul.lo.u64 %elem_off, %elem_off, 2;
    add.u64 %addr_in, %in, %elem_off;
    ld.global.f16 %x_f16, [%addr_in];
    // convert to fp32 and square
    cvt.f32.f16 %x_f32, %x_f16;
    mul.f32 %sq_f32, %x_f32, %x_f32;

    // ------------------------------------------------------------------
    // In-warp reduction (sum of squares)
    // ------------------------------------------------------------------
    mov.f32 %sum_f32, %sq_f32;

    // reduction using shfl.sync.down
    .reg .u32 %mask;
    mov.u32 %mask, 0xffffffff;

    shfl.sync.down.f32 %other_f32, %sum_f32, 16, %mask;
    add.f32 %sum_f32, %sum_f32, %other_f32;
    shfl.sync.down.f32 %other_f32, %sum_f32, 8, %mask;
    add.f32 %sum_f32, %sum_f32, %other_f32;
    shfl.sync.down.f32 %other_f32, %sum_f32, 4, %mask;
    add.f32 %sum_f32, %sum_f32, %other_f32;
    shfl.sync.down.f32 %other_f32, %sum_f32, 2, %mask;
    add.f32 %sum_f32, %sum_f32, %other_f32;
    shfl.sync.down.f32 %other_f32, %sum_f32, 1, %mask;
    add.f32 %sum_f32, %sum_f32, %other_f32;

    // ------------------------------------------------------------------
    // Write partial sum from each warp to shared memory
    // ------------------------------------------------------------------
    // Determine warpId = tid / 32
    shr.u32 %warpId, %tid, 5;
    setp.eq.u32 %p, %lane, 0;
    @%p st.shared.f32 [shmem + %warpId*4], %sum_f32;

