    // ------------------------------------------------------------------
    // Block-wide reduction of the two partial sums
    // ------------------------------------------------------------------
    bar.sync 0;

    // Thread 0 computes total sum, RMS and stores to shared[0]
    setp.eq.u32 %p, %tid, 0;
    @%p {
        ld.shared.f32 %total_f32, [shmem];
        ld.shared.f32 %other_f32, [shmem + 4];
        add.f32 %total_f32, %total_f32, %other_f32;   // total sum of squares

