        cvt.f32.u32 %total_f32, %nf;               // reuse total_f32 as divisor
        div.f32 %mean_f32, %total_f32, %total_f32; // mean = sum / N

        // add epsilon and sqrt
        add.f32 %mean_f32, %mean_f32, %eps_f32;
        sqrt.approx.f32 %rms_f32, %mean_f32;

        // store RMS for all threads
        st.shared.f32 [shmem], %rms_f32;
    }

    bar.sync 0;

    // ------------------------------------------------------------------
    // Broadcast RMS to all threads
    // ------------------------------------------------------------------
    ld.shared.f32 %rms_f32, [shmem];

    // ------------------------------------------------------------------
    // Write normalized output (if thread participated)
    // ------------------------------------------------------------------
    setp.ge.u32 %p, %tid, %nf;
    @%p bra END_KERNEL;

    // out = x_f32 / rms_f32
    div.f32 %x_f32, %x_f32, %rms_f32;
    cvt.f16.f32 %y_f16, %x_f32;

    // address = out + (base_off + tid)*2
    cvt.u64.u32 %elem_off, %tid;
    add.u64 %elem_off, %base_off, %elem_off;
    mul.lo.u64 %elem_off, %elem_off, 2;
    add.u64 %addr_out, %out, %elem_off;
    st.global.f16 [%addr_out], %y_f16;

END_KERNEL:
    ret;
}

